import{_ as a,o as t,c as s,a5 as d}from"./chunks/framework.UjrY2eRK.js";const p=JSON.parse('{"title":"Add an isolated self-hosted Push Gateway UI","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr/0024-add-an-isolated-self-hosted-push-gateway-ui.md","filePath":"architecture/adr/0024-add-an-isolated-self-hosted-push-gateway-ui.md","lastUpdated":1788169631000}'),o={name:"architecture/adr/0024-add-an-isolated-self-hosted-push-gateway-ui.md"};function i(r,e,n,l,h,u){return t(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="add-an-isolated-self-hosted-push-gateway-ui" tabindex="-1">Add an isolated self-hosted Push Gateway UI <a class="header-anchor" href="#add-an-isolated-self-hosted-push-gateway-ui" aria-label="Permalink to &quot;Add an isolated self-hosted Push Gateway UI&quot;">​</a></h1><p>Self-hosted deployments may opt in to a Push Gateway UI served by the Bun target from the same origin as its versioned operator API and fixed OIDC routes. It authenticates Operator Identities through generic standards-based OIDC, keeps identities, sessions, audit, metrics, and operation state in a separate <code>/data/admin.sqlite</code> database, and ships with the Bun gateway as one image and release; the operator surface remains disabled by default.</p><p>The base Compose deployment remains delivery-only. An explicit administration override adds the browser and OIDC configuration, mounts Docker secrets, and keeps both SQLite databases and verified backups on the same persistent <code>/data</code> volume. Enabling the surface does not introduce a second service or origin.</p><p>The Cloudflare Worker exposes no operator surface, and Matrix notification delivery, public <code>/health</code>, and the delivery-critical gateway database remain independent of UI, OIDC, administration-database, and metrics failures. A bounded Bun Worker is permitted only to flush best-effort aggregate metrics without delaying Matrix requests; it does not coordinate delivery.</p><p>This decision supersedes the administration-UI exclusions in ADRs 0001 and 0019 and ADR 0020&#39;s placeholder-only UI boundary. It narrows ADR 0017&#39;s worker-thread exclusion solely for the isolated metrics flush; ADR 0017&#39;s shared delivery behavior and runtime-adapter boundaries otherwise remain in force.</p>',5)])])}const f=a(o,[["render",i]]);export{p as __pageData,f as default};
